import { LightningElement } from 'lwc';

const ICONS = {
pharmacy: 'data:image/png;base64,',
    hco: 'data:image/png;base64,',
    hcp: 'data:image/png;base64,'
};

export const HCP_RECORD_TYPES = new Set([
    'SDO_PersonAccounts',
    'Medical_Professional_HCP',
    'PersonAccount',
    'Business_Contact'
]);

export const ACCOUNT_THEME = {
    pharmacy: {
        kind: 'pharmacy',
        label: 'Pharmacy',
        color: '#176935',
        ink: '#ffffff',
        soft: '#e8f4ec',
        border: '#b7dcc4'
    },
    hco: {
        kind: 'hco',
        label: 'HCO',
        color: '#fdbf29',
        ink: '#3a2a00',
        soft: '#fff6dc',
        border: '#f3d98a'
    },
    hcp: {
        kind: 'hcp',
        label: 'HCP',
        color: '#3f7de5',
        ink: '#ffffff',
        soft: '#eaf1fc',
        border: '#c5d7f6'
    },
    account: {
        kind: 'account',
        label: 'Account',
        color: '#032d60',
        ink: '#ffffff',
        soft: '#eef2f6',
        border: '#c9d3df'
    }
};

export function accountTypeIconUrl(kind) {
    return ICONS[kind] || '';
}

export function resolveAccountThemeKind(recordTypeDeveloperName, recordTypeName) {
    const developerName = recordTypeDeveloperName || '';
    const label = String(recordTypeName || '').toLowerCase();
    if (developerName === 'Pharmacy' || label.includes('pharmacy')) {
        return 'pharmacy';
    }
    if (
        HCP_RECORD_TYPES.has(developerName) ||
        label.includes('hcp') ||
        label.includes('doctor') ||
        label.includes('professional') ||
        label.includes('person')
    ) {
        return 'hcp';
    }
    if (
        developerName === 'Institution_HCO' ||
        label.includes('hco') ||
        label.includes('institution') ||
        label.includes('clinic') ||
        label.includes('hospital')
    ) {
        return 'hco';
    }
    return 'account';
}

export function accountThemeFor(recordTypeDeveloperName, recordTypeName) {
    const kind = resolveAccountThemeKind(recordTypeDeveloperName, recordTypeName);
    const theme = ACCOUNT_THEME[kind] || ACCOUNT_THEME.account;
    return {
        ...theme,
        iconUrl: accountTypeIconUrl(kind)
    };
}

export default class AccountTypeTheme extends LightningElement {}

export function accountThemeStyle(theme) {
    if (!theme) {
        return '';
    }
    return [
        `--account-theme:${theme.color}`,
        `--account-theme-ink:${theme.ink}`,
        `--account-theme-soft:${theme.soft}`,
        `--account-theme-border:${theme.border}`
    ].join(';');
}